export interface ModalInstance {
  element: HTMLElement;
  open(): void;
  close(): void;
  destroy(): void;
}

export interface CreateModalOptions {
  onClose?: () => void;
}

let openModalCount = 0;

const lockBodyScroll = (): void => {
  openModalCount += 1;
  document.body.classList.add('modal-open');
};

const unlockBodyScroll = (): void => {
  openModalCount = Math.max(openModalCount - 1, 0);

  if (openModalCount === 0) {
    document.body.classList.remove('modal-open');
  }
};

export const createModal = (
  root: HTMLElement,
  options: CreateModalOptions = {}
): ModalInstance => {
  const closeButton = root.querySelector<HTMLElement>('[data-modal-close]');
  const lifecycleController = new AbortController();

  let isOpen = false;
  let lastFocused: HTMLElement | null = null;

  const handleKeydown = (event: KeyboardEvent): void => {
    if (event.key === 'Escape') {
      close();
    }
  };

  const handleOverlayClick = (event: MouseEvent): void => {
    if (event.target === root) {
      close();
    }
  };

  const open = (): void => {
    if (isOpen) {
      return;
    }

    isOpen = true;
    lastFocused = document.activeElement as HTMLElement | null;

    root.classList.add('is-open');
    lockBodyScroll();
    document.addEventListener('keydown', handleKeydown);
    root.addEventListener('click', handleOverlayClick);

    closeButton?.focus();
  };

  const close = (): void => {
    if (!isOpen) {
      return;
    }

    isOpen = false;

    root.classList.remove('is-open');
    unlockBodyScroll();
    document.removeEventListener('keydown', handleKeydown);
    root.removeEventListener('click', handleOverlayClick);

    lastFocused?.focus();
    options.onClose?.();
  };

  const destroy = (): void => {
    close();
    lifecycleController.abort();
  };

  closeButton?.addEventListener('click', close, {
    signal: lifecycleController.signal,
  });

  return { element: root, open, close, destroy };
};
